程序1 数值积分求球冠体体积程序主要代码 
double qiuguan(double h) 
{ 
 double a = 1000, R = 1625, y = h; 
 double Ra = R - a; 
 double n = 1000; /*迭代100000 次*/ 
 double temp = (y + 1500.0) / n; 
 y = -1500; 
 double out = 0; 
 for (int i = 0; i < n; i++) 
 { 
 double r = sqrt(R * R - y * y); 
 double L = 2.0 * sqrt(r * r - Ra * Ra); 
 out += (r * r * acos(Ra / r) - L * Ra / 2.0 ) * temp; 
 y += temp; 
 } 
 return( out / 1e6); 
} 


